begin;

with input_items as (
  select *
  from jsonb_to_recordset($seed_json$[]$seed_json$::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    aliases text[],
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.aliases, '{}'::text[]) as aliases,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  aliases = excluded.aliases,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset($seed_json$[{"id": "b25ddeff-bf10-5fb4-bc50-d57bf1802c5a", "feature_slug": "web-article-copy", "title": "PART 1: Strategy — What to Write and Why", "content": "### 1. Every Article Serves a Search Journey Stage\n\nBefore writing, identify where the article sits:\n\n| Stage | Reader mindset | Keyword shape | Article job |\n|---|---|---|---|\n| **Problem-aware** | \"I have a problem, I don't know the solution category\" | \"ลูกค้าไม่กลับมาซื้อซ้ำ ทำไง\" | Name the problem, introduce the category |\n| **Category-aware** | \"I know the category, I'm learning about it\" | \"Loyalty Program คืออะไร,\" \"Martech คืออะไร\" | Educate comprehensively, become the reference |\n| **Solution-aware** | \"I know solutions exist, I'm comparing\" | \"เลือก CRM อย่างไร,\" \"Points vs. Tier\" | Help them evaluate honestly |\n| **Product-aware** | \"I know your product, I need proof\" | \"Rocket CRM รีวิว,\" case studies | Prove with evidence |\n\nWrite for one stage per article. Mixing stages creates confused content that satisfies no one.\n\n### 2. Topic Clusters, Not Isolated Posts\n\nArticles don't work alone. They work as clusters (HubSpot's pillar-cluster model):\n\n- **Pillar article** — comprehensive, 3,000–5,000+ words, owns the core topic (\"Martech คืออะไร\")\n- **Cluster articles** — focused, 800–2,500 words, own subtopics (\"CDP คืออะไร,\" \"วิธีสร้าง Loyalty Program\")\n- **Internal links** — pillar links to clusters, clusters link back to pillar, both link to relevant landing pages\n\nTopical authority compounds. Google rewards sites that demonstrate deep, interconnected expertise on a subject — not sites with one good article surrounded by unrelated content.\n\n### 3. Write What Only You Can Write\n\nHubSpot's core principle: if an LLM could produce the same article from publicly available information, you haven't added enough value.\n\nSources of original value for Rocket articles:\n- **Platform data** — anonymized benchmarks, feature usage patterns, outcome statistics\n- **Customer stories** — real before/after scenarios (with permission)\n- **Practitioner perspective** — opinions, frameworks, and recommendations that come from operating in the Thai market\n- **Contrarian takes** — challenge assumptions the reader holds (\"ระบบสมาชิกแบบเก่า ไม่ใช่ Loyalty Program จริง\")\n\nThe test: would someone who read the top 3 ranking articles find something new, useful, and non-obvious here? If not, rewrite.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-1-strategy-what-to-write-and-why", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-1-strategy-what-to-write-and-why", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "af8bc6f0450c3dd863f2405f57a36f1383a571897c017ed7aa40ecb6da0e1198", "truncated": false}, "is_active": true}, {"id": "cfe66ba5-d8dd-5ae7-b4c1-f3bb5dbf4b72", "feature_slug": "web-article-copy", "title": "PART 2: Structure — How to Organize an Article", "content": "### 4. The Macro Structure\n\nLong-form articles follow a chapter-based architecture. This is the structure that works (extracted from high-performing content):\n\n```\n1. HOOK + PROMISE (introduction)\n   — Why this matters right now\n   — What the reader will know after finishing\n   — Who this article is for\n\n2. FOUNDATION (define the concept)\n   — Clear definition, no jargon fog\n   — A concrete story or scenario that makes the abstract tangible\n   — \"Why should I care?\" answered within the first 300 words\n\n3. FRAMEWORK (organize the landscape)\n   — Categorize, classify, map the territory\n   — Give the reader a mental model they can reuse\n   — Use tables, diagrams, or numbered systems\n\n4. DEEP SECTIONS (the meat)\n   — Each section = one subtopic, self-contained\n   — Each section follows: concept → example → implication\n   — Progressive depth — start accessible, go expert-level\n\n5. PROOF (case studies, data, examples)\n   — Problem → Process → Result format\n   — Hard numbers, not vague claims\n   — Multiple industries/contexts to broaden relevance\n\n6. ACTION (what to do next)\n   — Practical takeaways\n   — Soft transition to Rocket (if relevant)\n   — Link to deeper resources or landing pages\n\n7. CONCLUSION (summarize + bridge)\n   — Restate the key insight (not just list section titles)\n   — Connect back to the reader's world\n   — Final CTA — earned, not forced\n```\n\n### 5. Logical Architecture: Pyramid + MECE\n\nFor universal pyramid, MECE, and same-level rules, see `CORE_WRITING_PRINCIPLES.md`. Below is article-specific application.\n\nTwo principles govern how sections and sub-points relate:\n\n**Pyramid Structure (Minto)**\nLead with the answer, not the buildup. Each section opens with its key point; supporting details follow beneath. Vertically, every sub-point must directly support its parent — if removing it doesn't weaken the parent argument, cut it.\n\nFor article introductions, use SCQA: Situation (context) → Complication (problem) → Question (what the reader needs answered) → Answer (what this article delivers).\n\n**MECE Sections**\nAt each level of the outline, sections must be mutually exclusive (distinct, minimal overlap) and collectively exhaustive (no major gaps — the reader never thinks \"wait, what about X?\").\n\n- **ME ≠ no cross-references.** Section A can briefly mention Section B (\"we cover this in [section]\") and Section B can recap relevant details from A. Cross-references strengthen flow — just don't duplicate the full explanation in both places.\n- **CE = completeness.** After reading all sections at a given level, the reader has the full picture for that level.\n\n**Same Abstraction Level**\nPoints and sub-points at each level must sit at the same abstraction level. Don't mix strategic principles with tactical steps in the same list. Don't mix category-level items with specific examples under the same heading level.\n\n**Section Flow + Recaps**\nSections aren't isolated blocks. Connect each to the previous one with bridge sentences or transitions that show how they relate.\n\nWhen preceding sections were complex, open the next section with a brief recap: \"จนถึงตอนนี้ เราได้ดู X และ Y แล้ว — ในส่วนนี้ เราจะเจาะ Z ซึ่ง...\" This orients the reader on where they are in the overall structure and how the new topic fits in.\n\n### 6. The Scenario-First Explanation\n\nAbstract concepts are invisible. The preferred technique: **introduce a fictional (or real) brand scenario before explaining the theory.**\n\nExample from the Martech article: instead of defining \"Martech Stack\" in abstract terms, the article creates a fictional brand \"Naturals\" and walks the reader through their entire customer journey — showing each Martech tool in action. The definition follows the story, not the other way around.\n\nPattern:\n1. \"ลองจินตนาการว่า...\" or \"สมมุติว่าคุณขาย...\"\n2. Walk through the scenario step by step\n3. Name the tools/concepts as they appear naturally in the story\n4. Then formalize the definition\n\nThis is \"show, then tell\" — the opposite of textbook writing.\n\n### 7. The Case Study Formula\n\nWhen presenting real examples, use this consistent structure:\n\n```\nBrand context (who, what industry, what scale)\n    ↓\nProblem (specific, measurable pain — not vague)\n    ↓\nProcess (what they did, which tools/features, how)\n    ↓\nResult (hard numbers: %, counts, timeframes)\n```\n\nMinimum three case studies per pillar article, from different industries. This signals breadth and prevents the reader from thinking \"that only works for [one type of business].\"\n\n### 8. Heading Hierarchy and Scannability\n\nReaders scan before they read. Headings are the article's skeleton — they must make sense even if the reader reads nothing else.\n\nRules:\n- **H1**: one per page, contains primary keyword, states what the article is\n- **H2**: major sections — each should be a standalone question a reader might search\n- **H3**: subsections within H2s — breakdowns, steps, or categories\n- **H4**: rare — only for deeply nested detail\n- Every H2 and H3 should pass the \"standalone search\" test: could someone Google this heading and reasonably expect to find this content?\n- Use chapter numbers (บทที่ 1, บทที่ 2) for pillar-length content to give the reader a sense of progress and structure\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-2-structure-how-to-organize-an-article", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-2-structure-how-to-organize-an-article", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "2705923d3a7ff72f0735a8947b8f2e8044703f86c1717b94a8b4b00f27568e1d", "truncated": false}, "is_active": true}, {"id": "f4121a74-6080-56de-804a-fea1a85b12ea", "feature_slug": "web-article-copy", "title": "PART 3: Writing — How to Write Each Section", "content": "### 9. The Hook\n\nThe first 150 words determine whether someone reads or bounces. Three hook strategies that work for knowledge content:\n\n**Timeliness hook** — tie to a current trend or moment:\n> \"ในปี 2026 Martech ได้ถูกกล่าวถึงเป็นอย่างมาก เป็นอีกเทรนด์ที่มาแรง...\"\n\n**Challenge hook** — question the reader's existing knowledge:\n> \"คุณคิดว่าคุณรู้จัก Martech คืออะไรอย่างแท้จริงหรือไม่?\"\n\n**Promise hook** — tell them exactly what they'll get:\n> \"หลังจากอ่านบทความนี้แล้วคุณจะเข้าใจมากขึ้นว่า...\"\n\nBest practice: combine two. Timeliness + Promise or Challenge + Promise. Never open with a dictionary definition.\n\n### 10. Explain Like a Strategist, Not a Textbook\n\nThe tone is a knowledgeable colleague explaining something over coffee — not a professor lecturing.\n\n| Do | Don't |\n|---|---|\n| Use \"คุณ\" to address the reader directly | Write in third person academic style |\n| Ask rhetorical questions to guide thinking | Make statements without grounding them |\n| Use \"เช่น\" and \"ตัวอย่างเช่น\" liberally | Leave abstract claims unillustrated |\n| Bold key terms on first introduction | Bold everything (emphasis fatigue) |\n| Transition between sections with a bridge sentence | Jump between sections without connection |\n\n### 11. Progressive Disclosure\n\nStart each section with what 80% of readers need. Then go deeper for the 20% who want more.\n\nPattern:\n1. State the concept in one sentence\n2. Explain why it matters (one paragraph)\n3. Show a concrete example\n4. Go deeper — nuances, edge cases, advanced technique\n5. (Optional) Link to a dedicated article for the full deep-dive\n\nThis respects the reader's time while rewarding those who stay.\n\n### 12. Framework Thinking\n\nReaders remember frameworks. Whenever you can organize information into a named system — do it.\n\nExamples from the Martech article:\n- Marketing Funnel as an organizing framework (Attract → Engage → Convert → Retain → Delight)\n- Martech Stack as a layered system (Ads → E-commerce → CDP → Automation → Loyalty)\n- 3A Framework for Loyalty (Attract, Amaze, Activate)\n\nWhen creating frameworks:\n- Give it a name if it's original (\"3A Framework\")\n- Keep it to 3–5 elements (cognitive limit)\n- Make elements parallel in grammar and abstraction level\n- Use the framework consistently throughout the article\n\n### 13. Bold + Inline Definitions for Jargon\n\nWhen introducing a technical term:\n- **Bold** it on first use\n- Define it inline or in the next sentence\n- Keep the English term in English (CRM, CDP, Churn Rate, Retention)\n- Don't define it again later — trust the reader\n\nExample:\n> \"แบรนด์ Naturals ยังมี **Loyalty Program** ที่บริหารจัดการโดย Rocket Loyalty CRM ซึ่งมอบรางวัลให้แก่ลูกค้าสำหรับทุกการกระทำ\"\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-3-writing-how-to-write-each-section", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-3-writing-how-to-write-each-section", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "1342d50e3c5ae1314f6329bba0d537e5394b6e1e951ac71d6cba28d433f7fd45", "truncated": false}, "is_active": true}, {"id": "aa0d98b2-315e-54ee-9731-8b8a4338c3d9", "feature_slug": "web-article-copy", "title": "PART 4: SEO — Making Articles Findable", "content": "### 14. Keyword Placement (Non-Negotiable)\n\n| Signal | Requirement |\n|---|---|\n| **Title tag / H1** | Primary keyword appears. Clear, not clever |\n| **Meta description** | Keyword once. Benefit + promise. Under 155 chars |\n| **First 100 words** | Keyword appears naturally |\n| **At least 2–3 H2s** | Keyword or close variant |\n| **URL slug** | Keyword-based, hyphenated, short |\n| **Image alt text** | At least one image references the keyword |\n\n### 15. Semantic Completeness\n\nGoogle rewards articles that cover the topic comprehensively. Don't just use the keyword — use the vocabulary that naturally surrounds it.\n\nFor \"Martech คืออะไร\":\n- Related: Marketing Technology, CDP, CRM, Marketing Funnel, Automation\n- Use cases: B2C, E-commerce, FMCG, แบรนด์\n- Outcomes: ROI, Conversion Rate, Retention, Customer Lifetime Value\n\nWrite comprehensively and these terms appear naturally. Keyword-stuffing is visible and penalized.\n\n### 16. Internal Linking Strategy\n\nEvery article must link to:\n- **1–3 relevant landing pages** (placed at the natural \"I need a tool\" moment)\n- **2–5 related articles** (cluster structure)\n- **The pillar page** (if this is a cluster article)\n\nAnchor text rules:\n- Descriptive, keyword-rich — \"ระบบสะสมแต้ม Omnichannel\" not \"คลิกที่นี่\"\n- Placed at the moment the reader's intent shifts from learning to considering\n\n### 17. Title Formulas That Rank and Get Clicked\n\n| Formula | Example |\n|---|---|\n| **[Keyword] คืออะไร [angle]** | \"Martech คืออะไร มีกี่แบบ และมีประโยชน์อย่างไรต่อธุรกิจ\" |\n| **[Number] วิธี [desired outcome]** | \"6 วิธีเพิ่ม Retention Rate ด้วย Loyalty Program\" |\n| **วิธี [action] [keyword]** | \"วิธีสร้าง Loyalty Program สำหรับร้านค้าออนไลน์\" |\n| **[Keyword] vs. [Alternative]** | \"Points-based vs. Tier-based Loyalty: เลือกแบบไหนดี\" |\n| **คู่มือ [keyword] ฉบับสมบูรณ์** | \"คู่มือ Martech Stack ฉบับสมบูรณ์ สำหรับนักการตลาด\" |\n\nFor Thai SEO: put the keyword as early as possible in the title. The Thai reading pattern left-scans just like English.\n\n### 18. E-E-A-T Signals\n\nGoogle evaluates Experience, Expertise, Authoritativeness, Trustworthiness. Build these into every article:\n\n| Signal | How |\n|---|---|\n| **Experience** | Include real screenshots, customer outcomes, \"we've seen that...\" statements |\n| **Expertise** | Author bio with credentials. Depth of content that a generalist couldn't produce |\n| **Authoritativeness** | Cite reputable sources. Get backlinks from industry publications |\n| **Trustworthiness** | No exaggeration. Acknowledge limitations. Link to sources. Show publish/update dates |\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-4-seo-making-articles-findable", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-4-seo-making-articles-findable", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "a7aab214197b193aa1b4efb8cce5dc3d5a212dacf0e81e9a6d0b8f471d55508a", "truncated": false}, "is_active": true}, {"id": "3f182bdb-dc59-50c9-a0d5-f66ab4b92b11", "feature_slug": "web-article-copy", "title": "PART 5: Formatting — Making Articles Readable", "content": "### 19. Visual Rhythm\n\nLong articles need visual variety to prevent fatigue. Alternate between:\n\n- Short paragraphs (max 3 visual lines — mobile-first)\n- Bullet/numbered lists (for items with parallel structure)\n- Bold key terms (for scanning)\n- Tables (for comparisons, structures)\n- Pull quotes or callout boxes (for key insights)\n- Images, diagrams, screenshots (break text monotony)\n- Code-style blocks (for frameworks, processes)\n\nNever let two long paragraphs sit back-to-back without a visual break.\n\n### 20. List Discipline\n\nWhen using lists:\n- All items must be at the same abstraction level\n- All items must follow the same grammatical form (all start with verb, or all start with noun)\n- Bold the lead phrase, follow with explanation\n- 5–9 items is the sweet spot. More than 9 → group into sub-categories\n\n### 21. The Table of Contents\n\nFor articles over 1,500 words, include a table of contents after the introduction. This serves two purposes:\n1. Reader navigation (especially on mobile)\n2. Google can use TOC structure for jump-link rich results\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-5-formatting-making-articles-readable", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-5-formatting-making-articles-readable", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "abc07ae67eef05d28ec0a886df0218d63714c5c88b1f68d6e32860a44ee3c005", "truncated": false}, "is_active": true}, {"id": "d6220ca1-a227-562e-9c00-64fd664c2319", "feature_slug": "web-article-copy", "title": "PART 6: Product Integration — Selling Without Selling", "content": "### 22. The Earned CTA\n\nArticles are not landing pages. Product mentions must be **earned** — they appear only after the article has delivered genuine value.\n\n**Placement logic:**\n- **Top of article:** Zero product mention. Pure education.\n- **Mid-article (optional):** Brief contextual mention when the product naturally solves what's being discussed. One sentence, with a link. Never a paragraph-length pitch.\n- **Bottom of article:** Soft CTA — \"หากต้องการ [outcome], [link to landing page or demo].\" This is earned because the reader just spent 10 minutes learning from you.\n\n### 23. Show, Don't Pitch\n\nWhen Rocket features appear in an article, they should appear as **examples within educational content**, not as sales bullets.\n\nGood: \"ตัวอย่างเช่น แบรนด์เครื่องดื่มระดับ Global ใช้ Loyalty Program สร้าง Mission ซื้อสินค้าเพื่อสะสมคะแนน — ผลลัพธ์: สมาชิกเพิ่ม 30% ภายใน 1 เดือน\"\nBad: \"Rocket CRM มีฟีเจอร์ Mission ที่ช่วยให้แบรนด์สร้างแคมเปญได้ — คลิกนัด Demo ตอนนี้!\"\n\nThe reader should think \"this brand really knows Loyalty\" — not \"this is an ad disguised as an article.\"\n\n### 24. Case Studies as Social Proof\n\nWeave customer results into the educational narrative:\n- Don't isolate them in a \"Our Customers\" section\n- Place them where the reader is thinking \"does this actually work?\"\n- Use the Problem → Process → Result formula\n- Hard numbers always (%, revenue, timeframe)\n- Attribution at the level the customer allows (industry category if not named)\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-6-product-integration-selling-without-selling", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-6-product-integration-selling-without-selling", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "5f420db99413f1880793fd7b60bc7ce3dff8c2b911ee2909122e7bfb072b69e2", "truncated": false}, "is_active": true}, {"id": "937575e4-1fd2-568f-86ee-830052d19a66", "feature_slug": "web-article-copy", "title": "PART 7: Language — Thai + English", "content": "### 25. Same Rules as Landing Pages, Plus:\n\n- **English terms stay English:** AI, CRM, CDP, Dashboard, Omnichannel, Churn, ROI, Funnel, Retention, Engagement, Conversion, Segment, Personalization\n- **Cut Thai filler:** สามารถ...ได้, ทำการ, เพื่อที่จะ, ช่วยให้คุณสามารถ\n- **Use the reader's vocabulary:** \"ดึงรายงาน\" not \"เขียน Query\"\n- **Bilingual definitions on first use:** \"Customer Data Platform (CDP) หรือแพลตฟอร์มข้อมูลลูกค้า คือ...\"\n- **Article-specific:** longer sentences are acceptable in educational content, but each sentence should carry one idea. If it carries two, split it.\n- **Conversational transitions:** \"เราลองมาดูตัวอย่างกัน,\" \"ในส่วนต่อไป เราจะเจาะลึก...\" — guide the reader through the journey\n\n### 26. Keyword Density for SEO Articles\n\nSEO articles serve the algorithm AND the reader:\n- Primary keyword: 0.5–1.5% density (natural, not forced)\n- Keyword in first paragraph, last paragraph, and sprinkled in H2s\n- Long-tail variants and semantic synonyms count — don't repeat the exact keyword unnaturally\n- If a sentence reads awkwardly because of keyword insertion, rewrite the sentence. Readability always wins.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-7-language-thai-english", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-7-language-thai-english", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "e55819734aa1ed65ee50f7552bfef4afd13ebfa322b0441313c31d092d74341c", "truncated": false}, "is_active": true}, {"id": "580eac30-4988-5f72-be6c-13d700a4bb66", "feature_slug": "web-article-copy", "title": "PART 8: Quality Checklist", "content": "Before publishing, every article must pass:\n\n### Substance\n- [ ] Does this article teach something the top 3 ranking pages don't?\n- [ ] Would a subject-matter expert nod along, or catch errors?\n- [ ] Are all claims supported by examples, data, or logic?\n- [ ] Does at least one section contain original insight (data, framework, or contrarian take)?\n\n### Structure\n- [ ] Can someone scan only the headings and understand the article's argument?\n- [ ] Does every section follow concept → example → implication?\n- [ ] Does each section lead with its key point? (Pyramid — answer first, details below)\n- [ ] Are sections at each level MECE? (distinct topics, complete coverage, no gaps)\n- [ ] Are points/sub-points at the same abstraction level within each list or heading level?\n- [ ] Do transitions and bridge sentences connect sections? Recaps used after complex sections?\n- [ ] Is there a table of contents for articles over 1,500 words?\n- [ ] Are case studies in Problem → Process → Result format?\n\n### SEO\n- [ ] Primary keyword in: H1, meta description, first 100 words, URL, at least 2 H2s, 1 image alt\n- [ ] 1–3 internal links to landing pages at natural intent-shift moments\n- [ ] 2–5 internal links to related articles (cluster structure)\n- [ ] No orphan pages — this article links out and is linked to\n\n### Readability\n- [ ] No paragraph exceeds 3 visual lines on mobile\n- [ ] Lists use parallel grammar and abstraction level\n- [ ] Key terms are bolded on first use and defined inline\n- [ ] Visual variety: at least one table, list, or image per 500 words\n\n### Language\n- [ ] English terms stay English, Thai reads like Thai\n- [ ] No สามารถ...ได้, ทำการ, เพื่อที่จะ\n- [ ] Reader is \"คุณ,\" not a passive observer\n- [ ] Each sentence carries one idea\n\n### Product\n- [ ] Zero product pitch in the first 50% of the article\n- [ ] Product mentions appear as examples within educational content\n- [ ] Bottom CTA is earned — reader received genuine value first\n\n### Voice & Authenticity\n- [ ] First 3 paragraphs pass the \"Who Wrote This?\" test — at least one line signals lived experience\n- [ ] No AI-cliché openers (\"In today's rapidly evolving...,\" \"Let's dive in,\" \"Let's delve into\")\n- [ ] No AI power words used as filler: \"comprehensive,\" \"robust,\" \"leverage,\" \"seamless,\" \"cutting-edge,\" \"game-changer,\" \"elevate\"\n- [ ] Paragraph lengths vary — some short punches, some longer explorations. No robotic uniformity\n- [ ] Lists vary in length and item weight — not every list is exactly 5 items with identical structure\n- [ ] At least one moment of opinion, push-back, or \"here's what most people get wrong\"\n- [ ] Article improves if paragraph one is deleted? If yes, rewrite paragraph one\n- [ ] Swap \"Rocket\" for a competitor — if nothing feels off, add more original perspective\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-8-quality-checklist", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-8-quality-checklist", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "7a71db04132b39e5cdc2aae40b27a3849601716e1abdbe1c6979371de314e457", "truncated": false}, "is_active": true}, {"id": "9ee05bdb-a9c3-5615-97fc-b37810563f70", "feature_slug": "web-article-copy", "title": "PART 9: Voice — Sound Like a Human, Not a Machine", "content": "The fastest way to lose reader trust in 2026 is to publish content that reads like it was generated and lightly edited. Readers detect it, Google devalues it, and it erodes the expertise positioning that articles are meant to build.\n\n### 27. The Senior Consultant Voice\n\nThe default voice for all Rocket content is a senior consultant who happens to write well — not a copywriter performing expertise, and not an algorithm producing \"content.\"\n\nThink: someone who's sat in 200 client meetings, seen what actually works, and is sharing what they know with a peer. They have opinions. They have scars. They occasionally break structure because the point demands it.\n\n| Trait | What it sounds like |\n|---|---|\n| **Has a point of view** | States a position, then qualifies where needed — doesn't hedge every sentence with \"it depends\" |\n| **Rhythmic variety** | Short punches next to longer explanatory runs. The tempo changes with the idea |\n| **Breaks the fourth wall** | \"ตรงนี้ขอพูดตรงๆ ว่า...\" or \"สิ่งที่ไม่ค่อยมีใครบอกคือ...\" |\n| **Cites lived experience** | \"จากที่เห็นมา,\" \"แบรนด์ที่ทำได้ดีมักจะ...\" — not \"it is widely known that\" |\n| **Comfortable with asymmetry** | Not every paragraph is the same length. Not every list has the same number of items. Structure serves the idea, not the other way around |\n\n### 28. Kill AI Tell-Signs\n\nAI-generated content has recognizable fingerprints. Learn them, then actively break the patterns:\n\n| AI Pattern | What to Do Instead |\n|---|---|\n| Opens with \"In today's rapidly evolving...\" or \"ในยุคปัจจุบันที่...\" | Start with a specific fact, question, or scenario the reader recognizes |\n| \"Let's dive in,\" \"Let's explore,\" \"Let's delve into\" | Just start. Or one natural Thai transition: \"เรามาดูกัน\" — once, not every section |\n| Every list is exactly 5 items with mirror-image structure | Vary list lengths. Let some items run longer than others. Three items is fine. Seven is fine |\n| Every paragraph is 3–4 sentences, same cadence | One-sentence paragraphs hit hard. Six-sentence paragraphs are fine when the idea needs room. Mix it up |\n| \"It's important to note that...\" / \"It's worth mentioning...\" | If it's important, just say it. The framing is filler |\n| \"Comprehensive,\" \"robust,\" \"leverage,\" \"seamless,\" \"cutting-edge,\" \"game-changer,\" \"elevate\" | Concrete descriptions. Not \"robust analytics\" — \"analytics that show which campaigns drove repeat purchases\" |\n| \"In conclusion,\" \"To summarize,\" \"In summary\" | Restate the core insight in fresh words, or just make the closing point |\n| \"This ensures that...\" after every feature | Describe the outcome directly. \"Sales teams see the full picture\" not \"This ensures that sales teams have comprehensive visibility\" |\n| Excessive hedging: \"may,\" \"might,\" \"could potentially\" stacked on every claim | Take a stance. Qualify only when genuinely uncertain |\n| Emoji-laden lists or bullet formatting as a crutch for weak substance | Let the content carry itself. Formatting supports — it doesn't replace — good writing |\n\n### 29. Inject Personality Without Losing Authority\n\nThe goal is content that feels **authored** — like it came from a specific person with taste and experience, not a committee or an algorithm.\n\nTechniques:\n- **Parenthetical asides** — (ซึ่งส่วนใหญ่ยังทำไม่ได้) or (yes, this matters more than most teams think). Use sparingly; one or two per article\n- **Direct challenges** — \"ถ้าคุณยังใช้ Excel จัดการ Loyalty Program อยู่ — ถึงเวลาเปลี่ยนแล้ว\"\n- **Contrarian framing** — don't just echo conventional wisdom. Push back where you have evidence: \"หลายคนบอกว่า Points-based Loyalty ตายแล้ว ความจริงคือ ถ้าออกแบบดี มันยังทำงานได้ผลลัพธ์ที่ดี\"\n- **Storytelling over statements** — when a point could be made with a flat assertion or a 2-sentence story, choose the story\n- **Confident concessions** — \"ระบบนี้ไม่ใช่คำตอบสำหรับทุกธุรกิจ — แต่ถ้าคุณ [specific condition], มันเปลี่ยนเกม\"\n- **Unexpected specificity** — instead of \"many brands struggle with retention,\" say \"แบรนด์ F&B ที่มีสาขา 50+ มักเจอปัญหาเดียวกัน: ลูกค้าซื้อครั้งเดียวแล้วหายไป\"\n\n### 30. The Authenticity Filters\n\nRun every piece through these before publishing:\n\n1. **\"Who Wrote This?\"** — Read the first 3 paragraphs aloud. Could any AI chatbot or any brand have produced this? If yes, something is missing. There should be at least one moment that signals real experience\n2. **\"Would I Forward This?\"** — Would a marketing director send this to their team with \"อ่านนี่\"? Content worth sharing has a novel insight, a useful framework, or a perspective they haven't encountered\n3. **\"Delete Paragraph One\"** — AI-generated content front-loads throat-clearing. If the article reads better starting from paragraph two, paragraph one was filler. Rewrite it\n4. **\"Swap the Brand Name\"** — Replace \"Rocket\" with any competitor. If nothing feels off, the article lacks original perspective — add a take, data point, or framework only Rocket could provide\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-9-voice-sound-like-a-human-not-a-machine", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-9-voice-sound-like-a-human-not-a-machine", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "19945e55322cf648ef2a662efcdf58b2ecb18fb1163f382f5de38303a261ec74", "truncated": false}, "is_active": true}, {"id": "62155996-86c6-5984-ad54-c9fd9657f1d5", "feature_slug": "web-article-copy", "title": "Purpose of This Document", "content": "These principles govern long-form blog articles and knowledge content — not landing pages. Landing pages follow **Part 1** above. Articles follow different rules because they serve a different job: **teach first, sell never (or gently, at the end).**\n\nAn article succeeds when:\n1. It ranks for the target keyword\n2. A reader finishes it feeling smarter than when they started\n3. It earns trust that makes the reader consider Rocket when they're ready\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#purpose-of-this-document", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "purpose-of-this-document", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "2e4a7789cdb14c4bfcd6a28851fe2e8892a97eac5932f9421bae2a13ed5d6666", "truncated": false}, "is_active": true}, {"id": "041d2984-a0ec-57fb-a18d-054a69816c37", "feature_slug": "web-article-copy", "title": "Web — Blog & Articles — Overview", "content": "**When to use:** Blog posts, knowledge articles, thought leadership. Search journey, macro structure, E-E-A-T, consultant voice.\n**Source:** `WEB_PAGE_COPY_PRINCIPLES.md` (Part 2)\n**Genre:** `article`\n\nPart 2 — Blog & Knowledge Articles SEO blog and long-form knowledge content", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md", "metadata": {"genre": "article", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "overview", "part": 2, "feature_slug": "web-article-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "a2e1d70f4c4222c6d810c5e913ff0ad06d89651493bcb77302fbda51f3e5d4c9", "truncated": false}, "is_active": true}, {"id": "58f8d91e-7838-53bb-beac-987434edbe22", "feature_slug": "web-internal-linking", "title": "Core Principle", "content": "Every page on the site exists within a network. A page without internal links is an orphan — invisible to both readers and Google. Internal links do three jobs:\n\n1. **Pass authority** — pages with backlinks transfer ranking power to pages they link to\n2. **Guide the reader** — move them from education → evaluation → conversion\n3. **Signal topical depth** — Google uses internal link structure to understand which topics the site owns\n\n**Critical rule: never cross-link between languages.** A Thai page links only to Thai pages. A Japanese page links only to Japanese pages. A Taiwanese page links only to Taiwanese pages.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#core-principle", "metadata": {"genre": "linking", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "core-principle", "part": 4, "feature_slug": "web-internal-linking", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "fdfd3840b1018daf2bb9c4bba7d4a12f334891bcce45da8ec2177db102c57125", "truncated": false}, "is_active": true}, {"id": "1e96fb1e-e618-537d-a393-adfeff91a314", "feature_slug": "web-internal-linking", "title": "PART 1: The Link Architecture", "content": "### 1. Three Page Types, Three Link Roles\n\n| Page type | Role in link network | Links out to | Receives links from |\n|---|---|---|---|\n| **Product landing page** | Convert. Receive authority from blog. | Other product LPs (cross-sell). Minimal outbound — keep attention on conversion | Blog articles, pillar pages, other LPs |\n| **Blog / knowledge article** | Educate. Build authority. Funnel to LPs. | 1–3 product LPs + 2–5 related blog articles + pillar page | Other blog articles, pillar page, external backlinks |\n| **Pillar page** | Own the core topic. Hub for the cluster. | All cluster articles + primary product LP | All cluster articles link back, external backlinks |\n\n### 2. Target Tier System\n\nNot every page is an internal link destination. Some pages exist primarily to **feed** authority and traffic to higher-priority pages. The Lark page list (see Part 3) assigns a **Target Tier** to each page per language:\n\n| Target Tier | Meaning | Internal link behavior |\n|---|---|---|\n| **Tier 1** | Highest priority destination. Usually product LPs or key pillar pages. | Every related blog article MUST link to this page. Receives the most internal links. |\n| **Tier 2** | Important pages worth linking to when topically relevant. | Link to when a natural connection exists. Not every article needs to link here. |\n| **Tier 3** | Supporting content. May not need incoming links at all — its job is to feed Tier 1 and Tier 2 pages. | Focus on linking OUT to higher-tier pages. Incoming links are nice-to-have, not required. |\n| **No tier / blank** | Page exists but is not a priority target for this language. | Don't actively link to it. It may still link out to tiered pages. |\n\n**A page can have different target tiers per language.** For example, a page might be Tier 1 for Japanese but Tier 2 for Taiwanese — because search volume and strategic priority differ by market.\n\n### 3. The Cluster Model\n\nEvery topic cluster has one pillar and multiple supporting articles:\n\n```\nPILLAR PAGE (comprehensive guide)\n  ├── links to → Cluster Article A\n  ├── links to → Cluster Article B\n  ├── links to → Cluster Article C\n  └── links to → Product Landing Page (Tier 1)\n\nCluster Article A → links back to Pillar + links to Tier 1 LP\nCluster Article B → links back to Pillar + links to Tier 1 LP + links to Article A\nCluster Article C → links back to Pillar + links to Article B\n```\n\nThis two-way linking creates a web that tells Google: \"this site has deep, interconnected expertise on this topic.\"\n\n### 4. Cross-Linking Between Articles\n\nBlog articles don't just link to the pillar and LP — they link to each other when topics are related.\n\n**Rules:**\n- Link when the other article adds value the current article can't cover in depth\n- Use a natural transition: \"RFM分析 helps segment customers — see our full guide on [顧客分析の手法5選]\" (JP example)\n- Anchor text must be descriptive (keyword-rich), never \"click here\" or \"read more\"\n- Link in the body, not in a \"related articles\" sidebar (body links carry more weight)\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-1-the-link-architecture", "metadata": {"genre": "linking", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-1-the-link-architecture", "part": 4, "feature_slug": "web-internal-linking", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "45f317423b24e75bd2b9bec6637b50728e6bf4e8f853cc8342c7a242e636ab28", "truncated": false}, "is_active": true}, {"id": "a110a719-71fb-50e5-b73e-7177ba503416", "feature_slug": "web-internal-linking", "title": "PART 2: Page Inventory and LP Targets", "content": "### 5. The Lark Page List — Source of Truth\n\nThe master list of all pages, keywords, and target tiers is maintained in a Lark wiki document. **Access it via the Lark MCP tool** (not by URL fetch).\n\n**Lark document:** [Page list](https://j9i3g0573d.sg.larksuite.com/wiki/VOHXwvejHi9vnik0zEClJSAygyc?from=from_copylink)\n\n#### Row structure\n\nEach row = **one page** identified by a single **path** (e.g., `/loyalty-crm`, `/blog/what-is-rfm`). That page may exist in one, two, or all three languages. **The domain is NOT specified in the Lark doc** because one row can serve multiple languages.\n\nTo construct the full URL, combine the language's domain with the path:\n\n| Market | Domain | Full URL pattern |\n|---|---|---|\n| **Thai** | `https://rocket.in.th` | `rocket.in.th/[path]` — no language prefix (e.g., `rocket.in.th/loyalty-crm/`, `rocket.in.th/blog/what-is-rfm/`) |\n| **Japanese** | `https://rocketcrm.io/ja` | `rocketcrm.io/ja/[path]` (e.g., `rocketcrm.io/ja/loyalty-crm/`, `rocketcrm.io/ja/blog/what-is-rfm/`) |\n| **Taiwanese** | `https://rocketcrm.io/zh` | `rocketcrm.io/zh/[path]` (e.g., `rocketcrm.io/zh/loyalty-crm/`, `rocketcrm.io/zh/blog/what-is-rfm/`) |\n\n#### Column structure\n\n| Column | Description |\n|---|---|\n| **Path** | URL path for the page (shared across languages). e.g., `/loyalty-crm` or `/blog/what-is-rfm` |\n| **KW - TH** | Target keyword(s) for the **Thai** version of this page. If blank, this page does not exist in Thai. |\n| **KW - JA** | Target keyword(s) for the **Japanese** version. If blank, page does not exist in Japanese. |\n| **KW - TW** | Target keyword(s) for the **Taiwanese** version. If blank, page does not exist in Taiwanese. |\n| **Target Tier (TH)** | Target tier (1, 2, or 3) for the Thai version. Blank = not a priority target in Thai. |\n| **Target Tier (JA)** | Target tier for the Japanese version. |\n| **Target Tier (TW)** | Target tier for the Taiwanese version. |\n| **Role (TH)** | Page role for the Thai market: **pillar**, **cluster**, or **standalone**. See explanation below. |\n| **Role (JA)** | Page role for the Japanese market. |\n| **Role (TW)** | Page role for the Taiwanese market. |\n\n**How to determine which pages exist in a given language:** check the `KW` column for that language. If `KW - JA` has a value, the page exists in Japanese. If `KW - JA` is blank, it doesn't.\n\n#### Page Role per Market\n\nA page's role can differ by market. The **Role (TH)**, **Role (JA)**, and **Role (TW)** columns specify how each page functions in that market's content architecture:\n\n| Role | Meaning | Link behavior |\n|---|---|---|\n| **pillar** | Hub page that owns a core topic for this market. All cluster articles in the same topic link to and from this page. | Links out to every cluster article in its topic. Receives links from all of them. Also links to the primary product LP. |\n| **cluster** | Supporting article within a pillar's topic group. | Must link to its pillar page. Must link to the relevant Tier 1 product LP. Should cross-link to sibling cluster articles when topically relevant. |\n| **standalone** | Independent page — not part of a pillar/cluster group for this market. | Links to relevant Tier 1 and Tier 2 pages based on topic overlap. Does not need a pillar backlink. Other pages link to it only when naturally relevant. |\n\n**A page can have different roles per market.** For example, a page might be a **cluster** article under the loyalty pillar in Japanese, but a **standalone** page in Taiwanese if that market doesn't have a loyalty pillar yet. Always check the Role column for the specific language you're working in.\n\n### 6. Domain Mapping\n\n| Market | Domain | Blog path | LP path |\n|---|---|---|---|\n| **Thai** | `https://rocket.in.th` | `/blog/[slug]` | `/[slug]` (e.g., `/loyalty-crm/`, `/membership-crm/`) |\n| **Japanese** | `https://rocketcrm.io/ja` | `/ja/blog/[slug]` | `/ja/[slug]` (e.g., `/ja/loyalty-crm/`) |\n| **Taiwanese** | `https://rocketcrm.io/zh` | `/zh/blog/[slug]` | `/zh/[slug]` (e.g., `/zh/loyalty-crm/`) |\n\n**Never cross-link between languages.** A JP article must not link to a TW or TH page, and vice versa.\n\n### 7. Product LP Targets by Topic\n\nEach blog article funnels to a specific product LP based on topic relevance. Below are the product LPs with the exact keywords per language:\n\n#### `/loyalty-crm`\n\nPoints, tiers, loyalty program management.\n\n| Language | Keywords |\n|---|---|\n| **TH** | ระบบสะสมแต้ม, ระบบสะสมคะแนน, สะสมแต้ม, Loyalty CRM, ระบบ CRM |\n| **JA** | ポイント管理システム, ポイントシステム, ポイントカードシステム, ポイント制度 |\n| **TW** | 集點系統, 會員集點, 點數系統, 集章活動 |\n\n**Blog topics that funnel here:** loyalty programs, LTV, upsell/cross-sell, repeat rate, customer loyalty, brand loyalty, fan marketing, AOV, point programs\n\n#### `/membership-crm`\n\nMember management, segmentation, CRM analytics.\n\n| Language | Keywords |\n|---|---|\n| **TH** | ระบบสมาชิก, ระบบสมาชิกออนไลน์, ระบบบัตรสมาชิก |\n| **JA** | 会員管理システム, 会員管理, 会員管理アプリ, 会員管理ソフト |\n| **TW** | 會員管理系統, 會員經營, 會員系統, 會員管理, LINE會員系統, 會員行銷 |\n\n**Blog topics that funnel here:** RFM, churn, customer analysis, omnichannel, personalization, marketing automation, customer journey, engagement, touchpoints, segmentation\n\n#### `/membership-card`\n\nDigital membership cards.\n\n| Language | Keywords |\n|---|---|\n| **TH** | — (check Lark for current TH keywords) |\n| **JA** | デジタル会員証, 会員証 作成, 会員証 アプリ |\n| **TW** | 會員卡, 會員卡 app, LINE會員卡, 電子會員卡, 數位會員卡 |\n\n**Blog topics that funnel here:** membership card creation, digital vs physical cards, LINE membership cards\n\n#### `/reward-program`\n\nStamp cards, gamified rewards, missions.\n\n| Language | Keywords |\n|---|---|\n| **TH** | — (check Lark for current TH keywords) |\n| **JA** | スタンプカード アプリ, スタンプラリー アプリ, デジタルスタンプカード, ショップカード アプリ |\n| **TW** | LINE集點卡, 集點卡 |\n\n**Blog topics that funnel here:** gamification, restaurant/store customer acquisition, promotions, reward campaigns\n\nIf unsure which LP, pick the one whose feature set most directly solves the problem the article discusses.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-2-page-inventory-and-lp-targets", "metadata": {"genre": "linking", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-2-page-inventory-and-lp-targets", "part": 4, "feature_slug": "web-internal-linking", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "0cc8d79e8683d48a1746f01bb35250a4f94122f53fa564d9f1e9a65f09bb7081", "truncated": false}, "is_active": true}, {"id": "fced92ef-bdb1-5330-8b97-21c7c42aea83", "feature_slug": "web-internal-linking", "title": "PART 3: AI Workflow for Internal Linking", "content": "### 8. When Writing a New Article\n\n```\n1. IDENTIFY the language of the article being written\n2. FETCH the page list from Lark via the Lark MCP tool\n3. FILTER for the target language:\n   - Check the KW column for that language (KW - TH, KW - JA, or KW - TW)\n   - Pages with a value in that KW column exist in that language\n   - Pages with a blank KW column for that language do NOT exist — skip them\n4. NOTE the Target Tier AND Role for each page in that language:\n   - Target Tier: 1 = must link to, 2 = link when relevant, 3 = feeds others\n   - Role: pillar, cluster, or standalone — determines link structure\n5. DETERMINE this article's own role from the Role column:\n   - If CLUSTER → identify its pillar page. Link to pillar is mandatory.\n     Cross-link to sibling cluster articles in the same topic group.\n   - If PILLAR → identify all cluster articles in its topic. Link to each.\n   - If STANDALONE → no pillar relationship. Link based on topic overlap\n     and Target Tier only.\n6. CONSTRUCT full URLs using the domain mapping:\n   - TH: rocket.in.th/[path] (no language prefix)\n   - JA: rocketcrm.io/ja/[path]\n   - TW: rocketcrm.io/zh/[path]\n7. FIND related pages:\n   - Which Tier 1 pages should this article link to?\n   - Which Tier 2 pages cover topics this article mentions?\n   - Which blog articles share the same pillar (cluster siblings)?\n   - Which standalone articles cover overlapping topics?\n8. WRITE the article with links embedded at natural points:\n   - Links to Tier 1 target pages (mandatory)\n   - Link to pillar page (mandatory if this article's role = cluster)\n   - Links to cluster siblings (if this article's role = cluster or pillar)\n   - Links to related Tier 2 blog articles (when relevant)\n9. FLAG existing articles that should add a link back to this new article\n   - Output: list of URLs + suggested anchor text + suggested placement\n   - Prioritize flagging cluster siblings and the pillar page\n```\n\n**Remember:** the Lark doc does NOT include domain — one row can serve multiple languages. Always check the KW column for the specific language to confirm the page exists, then construct the URL using the domain mapping.\n\n### 9. When Reviewing an Existing Article\n\n```\n1. FETCH page list from Lark MCP\n2. IDENTIFY the article's language and filter pages for that language\n3. CHECK the article's Role for this language (pillar, cluster, or standalone)\n4. If CLUSTER:\n   - Does it link to its pillar page? (mandatory)\n   - Does it link to cluster siblings?\n   If PILLAR:\n   - Does it link to all cluster articles in its topic?\n   If STANDALONE:\n   - Are outbound links appropriate for topic overlap?\n5. CHECK: does it link to all relevant Tier 1 pages?\n6. CHECK: does it link to at least 2 related blog articles?\n7. CHECK: are anchor texts descriptive and keyword-rich?\n8. CHECK: are there new articles published since this was written that should be linked?\n9. CHECK: no cross-language links exist (TH→TH only, JA→JA only, TW→TW only)\n10. RECOMMEND specific links with:\n    - Target URL (full URL with correct domain)\n    - Anchor text\n    - Placement (which paragraph or section)\n```\n\n### 10. Link Opportunity Signals\n\nWhen two articles share any of these, they should link to each other:\n\n- **Same topic cluster** (e.g., both about loyalty → link)\n- **Concept dependency** (e.g., RFM article mentions \"churn\" → link to churn article)\n- **Metric ↔ Strategy** (e.g., \"repeat rate\" article ↔ \"loyalty program\" article)\n- **Problem ↔ Solution** (e.g., \"customer acquisition cost\" article ↔ \"referral program\" article)\n- **Same LP funnel** (e.g., both funnel to `/loyalty-crm` → link to each other)\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-3-ai-workflow-for-internal-linking", "metadata": {"genre": "linking", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-3-ai-workflow-for-internal-linking", "part": 4, "feature_slug": "web-internal-linking", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "e0cc170314e440e69cb11aed5b81587dd1254d2332d89e6bb7edb164e9a6fad8", "truncated": false}, "is_active": true}, {"id": "c780208a-4fd9-550b-b9d1-e3b84a018f68", "feature_slug": "web-internal-linking", "title": "Quick Reference", "content": "### Link Minimums per Page Type\n\n| Page type | Min links to Tier 1 | Min links to articles | Min links received | Anchor text rule |\n|---|---|---|---|---|\n| Blog (short) | 1 | 2 | 1+ | Keyword-rich, varied |\n| Blog (long / pillar) | 1–2 | 5+ (all cluster articles) | All cluster articles link back | Keyword-rich, varied |\n| Product LP | 2+ (cross-link other LPs) | 0–1 (optional pillar link) | All relevant blog articles | Product name or feature keyword |\n\n### No Cross-Language Linking\n\n| Article language | Can link to | Cannot link to |\n|---|---|---|\n| Thai (rocket.in.th) | Other rocket.in.th pages only | rocketcrm.io/ja/*, rocketcrm.io/zh/* |\n| Japanese (rocketcrm.io/ja) | Other rocketcrm.io/ja pages only | rocket.in.th/*, rocketcrm.io/zh/* |\n| Taiwanese (rocketcrm.io/zh) | Other rocketcrm.io/zh pages only | rocket.in.th/*, rocketcrm.io/ja/* |\n\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#quick-reference", "metadata": {"genre": "linking", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "quick-reference", "part": 4, "feature_slug": "web-internal-linking", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "8c547d2dfe1061b31862e9fa547792e01c1e096cf71e22baa16b183ef1b041fd", "truncated": false}, "is_active": true}, {"id": "545b557f-151d-5d8c-afcc-effc5f6e9550", "feature_slug": "web-internal-linking", "title": "Web — Internal Linking — Overview", "content": "**When to use:** Pillar-cluster architecture, LP target tiers, AI linking workflow, cross-language link rules.\n**Source:** `WEB_PAGE_COPY_PRINCIPLES.md` (Part 4)\n**Genre:** `linking`\n\nPart 4 — Internal Linking Cross-page link strategy for landing pages, pillars, and articles", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md", "metadata": {"genre": "linking", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "overview", "part": 4, "feature_slug": "web-internal-linking", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "43d89fe4bf638d88055aad28a70c028303adeab389e5be802141716125005713", "truncated": false}, "is_active": true}, {"id": "bd7ad243-22d8-5f6a-964c-40e4b630d562", "feature_slug": "web-landing-copy", "title": "I. Foundation: What the Page Must Do in 5 Seconds", "content": "---\n\n### 1. Instant Comprehension\n\nA visitor must understand **what it is** and **who it's for** within five seconds. If they scroll to guess, the page has already failed.\n\nThe hero section answers two questions only:\n1. What does this do?\n2. Is this for me?\n\nEverything else — features, proof, pricing — comes after.\n\n### 2. Customer is the Hero\n\nThe customer is the hero of the story. The brand is the guide. Every sentence should be about the customer's situation, not the brand's achievements.\n\n- **Brand as hero:** \"We built the first AI CRM\" / \"Rocket เป็น Loyalty CRM ตัวแรกที่ใช้ Agentic AI\"\n- **Customer as hero:** \"A CRM that sends the right offer to each customer automatically\" / \"ลูกค้าซื้อจากหลายช่องทาง ระบบรวมทุกยอดซื้อเป็นโปรไฟล์เดียวให้อัตโนมัติ\"\n\nThe first talks about Rocket. The second talks about the customer's reality, with Rocket as the tool that fixes it. Don't lead with brand history, awards, or what the company is \"trying to do.\" The reader doesn't care about your story. They care about theirs.\n\n### 3. No Metaphors\n\nBan \"unleash,\" \"supercharge,\" \"revolutionize,\" \"next-gen,\" \"cutting-edge.\" These are emotional placeholders where a specific claim should be.\n\n- **Metaphor:** \"Supercharge your customer engagement.\"\n- **Descriptive:** \"Automate your post-purchase follow-ups.\"\n\nThe second tells the reader exactly what happens. The first tells them you have a copywriter.\n\n**Exception — punchy taglines that generate emotion.** A short metaphor or provocative phrase is allowed as a hero tagline IF it creates genuine emotion — FOMO, inspiration, urgency, or a feeling of possibility. FlowAccount's \"รีเซ็ตธุรกิจ\" works because it's two words that make the reader feel something. The test: does the phrase trigger an emotional reaction, or is it just decoration? \"Supercharge your workflow\" is decoration. \"รีเซ็ตธุรกิจ\" is a provocation. This exception only applies to brand-level taglines and homepages where the audience already knows the product. On ads and SEO pages for cold traffic, descriptive copy always wins.\n\n### 4. No Vague Modifiers\n\nWords like \"ตามกลยุทธ์ของคุณ,\" \"ตามต้องการ,\" \"ที่ยืดหยุ่น,\" \"flexible,\" \"customizable\" feel specific but are empty. They describe *that* something is configurable without showing *what* changes. If you can't picture what the customization looks like, the modifier is doing nothing.\n\n- **Vague:** \"ระบบสะสมแต้มที่ออกแบบได้ตามกลยุทธ์ของคุณ\"\n- **Concrete:** \"ให้คะแนนได้มากกว่าแค่ยอดซื้อ — รีวิว ชวนเพื่อน Check-in ก็ให้คะแนนได้\"\n\nThe fix is always the same: replace the modifier with an example of what it enables.\n\n**Abstraction as container, not crutch.** High-level words are powerful when they attach to a category the reader already understands — they act as a clean container for the reader's mental model. Use them there; avoid them when they mask a vague concept or when you should be naming identity instead.\n\n- **Container (good):** \"Fully customizable CMS\" — the reader knows what a CMS is; \"customizable\" frames the scope.\n- **Crutch (bad):** \"Flexible loyalty solution\" — \"loyalty solution\" is already vague; \"flexible\" adds nothing concrete.\n- **Too low (bad):** \"Customizable headers and descriptions\" — correct but hurts the big picture on a hero or category headline.\n\n### 5. Outcome vs. Mechanism Balance\n\nBalance the promise of the result with the clarity of the tool. Sometimes they conflict — when they do, judge which one the reader needs more at that moment.\n\n**Default — sell the outcome:**\n- **Mechanism:** \"AI Analytics Dashboard.\"\n- **Outcome:** \"Get answers from your data in plain English.\"\n\n**Exception — high-intent buyers.** Most visitors arrive via search. They already know *what* they want. They're confirming *whether you have it*. For these readers, naming the mechanism builds confidence that you actually solve the problem, not just promise to.\n\n- \"One-click Shopify install\" — they searched for Shopify integrations, confirming mechanism matters more than outcome here.\n- \"Postgres database\" — a technical buyer needs to know the stack, not be told \"your data is safe.\"\n- \"Syncs orders in < 500ms\" — the outcome (synced orders) is obvious. The mechanism (speed) is the differentiator.\n\n**Third case — obvious outcome.** When the audience already knows the outcome of your product category, restating it is redundant. Everyone knows loyalty programs exist to drive retention and repeat purchases. Saying \"ระบบ CRM ที่ทำให้ลูกค้ากลับมาซื้อซ้ำ\" tells them nothing they didn't already know. In this case, skip the outcome entirely. Be ultra-clear about **what the product IS** and **who it's for** instead.\n\n- **Redundant outcome:** \"ระบบ CRM ที่ทำให้ลูกค้ากลับมาซื้อซ้ำ\"\n- **Ultra-clear identity:** \"ระบบสะสมแต้มสำหรับแบรนด์ B2C\"\n\n**How to decide:** Ask whether the reader already knows the outcome they want. If yes and the outcome is non-obvious, the mechanism is what closes the gap. If the outcome is obvious to the entire category, skip it — lead with identity and scope instead.\n\n### 6. Category Clarity Over Cleverness\n\nWhen a heading describes a capability, the reader must instantly know which product category they're looking at. If the same heading could describe three different product types, it's too abstract.\n\n- **Ambiguous:** \"รวมทุกช่องทางขายในที่เดียว\" — could be an order management system, an online store builder, or a CRM.\n- **Clear:** \"สะสมแต้มได้ครบทุกช่องทาง ไม่ว่าจะซื้อจากที่ไหน\" — unmistakably about loyalty points across channels.\n\nIndustry terms like \"Omnichannel\" are useful here precisely because they anchor the reader in the right category. Don't avoid jargon when the jargon is what the reader is looking for. But the sentence must still read naturally — if adding the term makes it clunky, restructure the sentence around it.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#i-foundation-what-the-page-must-do-in-5-seconds", "metadata": {"genre": "landing", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "i-foundation-what-the-page-must-do-in-5-seconds", "part": 1, "feature_slug": "web-landing-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "3e289b15bbcffa3509cdcf555d654304ccbf6eb19000aae2d49048437a9a1125", "truncated": false}, "is_active": true}, {"id": "bea629fa-3b7b-5d97-ae0a-df464e35d44c", "feature_slug": "web-landing-copy", "title": "II. Expression: How to Communicate Features Effectively", "content": "---\n\n### 7. Mental Validation\n\nWhen you claim \"comprehensive\" or \"all-in-one,\" the reader doesn't believe you until you prove it. Proof is a list of recognizable components that match the checklist already in their head.\n\nA buyer shopping for a loyalty platform already knows what one should contain. They're scanning for confirmation. Name those components so they can mentally check each box.\n\n**Good:**\n> ระบบสมาชิก, สะสมแต้ม, แลกคูปอง, แลกรับของรางวัล, วิเคราะห์พฤติกรรมลูกค้า, Dashboard รวมข้อมูลลูกค้าทั้งหมด\n\nSix items. Six yeses.\n\n**Bad:**\n> \"Comprehensive loyalty platform with everything you need.\"\n\nZero yeses. The reader has to trust you instead of verify you. They won't.\n\n**Constraint 1 — same level of abstraction.** Every item must be the same \"size.\" This applies to feature grids, bento boxes, step lists, and comparison rows — anywhere the reader scans a set of peers in one glance.\n\n- **Consistent:** Tiers, Rewards, Campaigns, Points, Analytics\n- **Broken:** Tiers, Rewards, LINE Notification, Custom Form\n\nThe second jumps from strategic modules to implementation details. It feels wrong even if the reader can't say why. It's listing \"Bedroom, Kitchen, Garden, Doorknob.\"\n\n**Constraint 2 — same grammatical form.** Items in a list should be the same type of phrase — all nouns, or all verb phrases. Mixing them makes the list feel jumbled even if the abstraction level is consistent.\n\n- **Jumbled:** \"สมาชิก สะสมแต้ม แลกรางวัล แคมเปญ วิเคราะห์ลูกค้าด้วย AI\" — mixes bare nouns (สมาชิก, แคมเปญ), verb phrases (สะสมแต้ม, แลกรางวัล), and a clause (วิเคราะห์ลูกค้าด้วย AI).\n- **Consistent (all nouns):** \"ระดับสมาชิก สะสมแต้ม แลกรางวัล แคมเปญ AI Analytics\"\n- **Consistent (all verb phrases):** \"ตั้งระดับสมาชิก สะสมแต้ม แลกรางวัล สร้างแคมเปญ วิเคราะห์ลูกค้า\"\n\nAlso check that each item conveys the right meaning. \"สมาชิก\" alone means \"member\" — it doesn't convey the tier system. \"ระดับสมาชิก\" does.\n\n**Qualifiers are allowed if proven immediately.** Words like \"ครบวงจร,\" \"หลายมิติ,\" or \"ครบทุกฟีเจอร์\" are generic on their own. But if the very next sentence is a concrete list that proves the claim, the qualifier becomes a useful preview — it tells the reader what to expect before the evidence arrives. \"แคมเปญหลายมิติ\" followed by five specific campaign types is earned. \"แคมเปญหลายมิติ\" followed by nothing is fluff.\n\n### 8. Narrative Mechanics\n\nAbstract features — \"omnichannel,\" \"unified profile,\" \"real-time sync\" — are invisible. They describe a state. States don't move. The brain processes movement.\n\nTo make a feature real, describe **what happens** — the data moving or the customer moving through the system.\n\n**Good:**\n> ไม่ว่าลูกค้าจะซื้อผ่านช่องทางไหน ออนไลน์ ออฟไลน์ หรือ Marketplace ทุกยอดซื้อถูกบันทึกและคำนวณคะแนนให้อัตโนมัติ รวมเป็นโปรไฟล์ลูกค้าเดียวในระบบ CRM\n\nA micro-story. The reader watches a customer buy somewhere, then watches data flow into one profile. They see it happen. That is comprehension.\n\n**Bad:**\n> \"Unified customer profile across all channels.\"\n\nSame thing technically. But nobody can picture it.\n\n**When to use:** Any time the capability spans multiple touchpoints, channels, or time periods. The more abstract the feature, the more it needs a concrete step-by-step of what actually happens.\n\n### 9. Success Vision\n\nNarrative Mechanics describes how the product works (feature-level). Success Vision describes how the customer's life changes (outcome-level). Paint a concrete scene of their daily work *after* they use the product.\n\n- **Abstract outcome:** \"เพิ่มยอดซื้อซ้ำ\"\n- **Success vision:** \"เปิด Dashboard เห็นทันทีว่าใครกำลังจะ Churn ใครพร้อมอัพเกรด Tier\"\n- **Success vision:** \"AI ส่งข้อเสนอให้ลูกค้าแต่ละรายอัตโนมัติ ไม่ต้องเลือกเอง\"\n\nThe reader should be able to picture a specific moment in their workday that becomes better. Not a vague improvement — a concrete scene.\n\n### 10. Operational Utility\n\n**Strategic label, operational proof.** Pair an abstract noun (the capability category) with daily workflow verbs (what actually happens). Use the heading for strategic value; use the line below for operational utility.\n\n| Strategic (heading) | Operational (description) |\n|---|---|\n| Advanced Churn Prediction | AI detects when a customer stops buying and sends a win-back offer. |\n| Omnichannel Loyalty | Every purchase — online, offline, or marketplace — earns points into one profile automatically. |\n\nIf the description only repeats the heading in longer words, rewrite the description with verbs the operator or customer performs.\n\nTechnology names — AI, machine learning, automation — mean nothing until you define exactly **which decision or task** the technology handles so the human doesn't have to.\n\nDon't sell the tool. Sell the specific thinking it removes.\n\n**This applies to all features, not just AI.** Describe every feature using verbs the user performs daily. FlowAccount doesn't say \"comprehensive financial management solution\" — they say \"เปิดบิล บันทึกค่าใช้จ่าย จัดการสต็อก ลงบัญชี.\" Four daily actions. The reader immediately sees their own workflow reflected. Apply the same pattern to loyalty: \"สร้างแคมเปญชวนเพื่อน,\" \"ตั้งเงื่อนไขให้คะแนน,\" \"ดูรายงาน Campaign ROI\" — not \"campaign management,\" \"points configuration,\" \"analytics dashboard.\"\n\n**Good:**\n> ใช้ AI วิเคราะห์พฤติกรรมลูกค้า แนะนำสิทธิพิเศษหรือของรางวัลที่เหมาะสมกับลูกค้าแต่ละราย\n\n**Bad:**\n> \"AI-powered personalization.\"\n\n**Test:** Remove the word \"AI.\" If the sentence still communicates value, it's written correctly. If it collapses, you sold a label, not relief.\n\n**AI as subject, not modifier.** When describing AI capabilities, make AI the grammatical subject performing specific verbs — not a modifier tacked onto the end of a sentence. \"ด้วย AI\" and \"powered by AI\" are labels. \"AI วิเคราะห์...และส่ง...\" is a capability.\n\n- **AI as modifier (bad):** \"วิเคราะห์ลูกค้าด้วย AI\" — \"ด้วย AI\" is bolted on. Remove it and the sentence becomes \"วิเคราะห์ลูกค้า\" — vague, no specific action.\n- **AI as subject (good):** \"AI วิเคราะห์ลูกค้าและส่งข้อเสนออัตโนมัติ\" — AI is the subject doing two verbs (วิเคราะห์ + ส่ง). The reader sees what happens.\n\nThis is especially important when the AI's value is in *taking action*, not just analyzing. If the AI predicts churn and sends an offer, the sentence must show both steps — analysis alone undersells the capability.\n\n**AI framing: augmentation, not replacement.** When the audience is the team that will use the product (marketers, operators), never frame AI as replacing them. \"AI ที่คิดแทนทีมคุณ\" reads as a threat, not a benefit. Instead, frame AI as enabling something the team *wants* to do but physically *can't* at scale.\n\n- **Threatening:** \"AI ที่คิดแทนทีมคุณ\"\n- **Empowering:** \"เหมือนมี AI เป็นนักการตลาดส่วนตัวให้ลูกค้าทุกคน\"\n\nThe AI isn't replacing them. It's multiplying them.\n\n_Source section truncated in seed; see `source_ref` for full text._", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#ii-expression-how-to-communicate-features-effectively", "metadata": {"genre": "landing", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "ii-expression-how-to-communicate-features-effectively", "part": 1, "feature_slug": "web-landing-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "a4965b20193bc3c03354efead7740702e9a0a220a6b8fb9f9f8f33f3544fceaa", "truncated": true}, "is_active": true}, {"id": "11a5714e-48a6-5bee-adcb-e22decf3f260", "feature_slug": "web-landing-copy", "title": "III. Persuasion: How to Frame the Message", "content": "---\n\n### 11. Three Layers of Problem\n\nEvery customer problem has three layers. Most copy only addresses the first. Addressing all three creates emotional resonance — the reader thinks \"they understand me,\" not just \"they have the feature I need.\"\n\n- **External (practical):** \"ข้อมูลลูกค้ากระจายอยู่หลายระบบ\"\n- **Internal (emotional):** \"ไม่รู้ด้วยซ้ำว่าลูกค้าคนเดียวกันซื้อจากกี่ช่องทาง\"\n- **Philosophical (why it's wrong):** \"แบรนด์ที่ลงทุนกับ Loyalty ไม่ควรต้องเดาว่าลูกค้าเป็นใคร\"\n\nThe external layer states the fact. The internal layer names how it feels. The philosophical layer validates that the reader's frustration is justified. You don't need all three in every sentence, but the page as a whole should touch all three levels.\n\n**Name real pain, not manufactured pain.** The problem you describe must be something the reader actually experiences — not something you constructed to fit your product's strengths. If the reader hasn't felt this frustration in their own work, the copy reads as manipulation, not empathy.\n\n- **Manufactured:** \"ไม่ต้องปะติดปะต่อหลายเครื่องมือ\" — sounds like a tool integration problem. If the reader isn't actually stitching together 5 tools today, this pain doesn't resonate.\n- **Real:** \"ฟีเจอร์รองรับแบรนด์ใหญ่ ในราคา SME\" — addresses a genuine objection: \"this looks powerful but probably costs more than I can afford.\"\n\n**Test:** Ask \"would the reader say this sentence to a colleague in a meeting?\" If nobody has ever complained about this problem out loud, you invented it.\n\n### 12. Objection Judo\n\nName the fear, dissolve it in the same line.\n\n| Fear | Copy |\n|---|---|\n| Setup takes forever | \"Launch in 3 hours, not 3 months.\" |\n| It's expensive | \"Enterprise features, SME price tag.\" |\n| I'll need a developer | \"No code. No developer. No ticket to IT.\" |\n\nStructure: **Specific fear → Specific counterclaim.**\n\n**Two forms of Objection Judo:**\n- **Inline** — dissolve the fear within feature copy. Handles \"should I keep reading?\"\n- **Structured (FAQ section)** — a dedicated section near the bottom that systematically addresses common objections: security, implementation time, support availability, pricing, technical requirements. Handles \"should I fill out this form?\" For enterprise/B2B SaaS, a FAQ section gives you a second chance to address objections the reader didn't even realize they had.\n\n### 13. Social Proof Placement\n\nPlace hard numbers (user count, brand count, transactions processed) between the hero and the feature sections. The reader should trust you before you start selling.\n\n- **Logo bar** (brand logos) confirms \"companies like mine use this.\"\n- **Hard numbers** (130,000+ ผู้ประกอบการ, 500+ แบรนด์) confirm scale.\n- **Position both early** — after the hero, before features. If the reader trusts you by the time they start reading features, every claim lands harder.\n\nNumbers must be specific and verifiable. \"Thousands of businesses\" is generic. \"500+ แบรนด์ B2C\" is specific. Round numbers feel made up. Odd numbers feel real.\n\n### 14. Hook Strategies\n\nAngles that give a headline its edge. Pick one per section. Never stack.\n\n**Contrast must be real opposition.** When using a contrast structure (\"X — not just Y\"), the two sides must be things the reader naturally sees as alternatives or trade-offs. If A and B aren't in tension in the reader's mind, the contrast creates confusion, not clarity.\n\n- **Broken contrast:** \"AI ที่ตัดสินใจได้ — ไม่ใช่แค่ Dashboard\" — AI is a decision layer, Dashboard is a display layer. Nobody chooses between them — they expect both.\n- **Real contrast:** \"AI ที่ลงมือทำเอง — ไม่ใช่แค่วิเคราะห์ให้คุณตัดสินใจ\" — \"acts autonomously\" vs \"just reports for you to decide\" is a real spectrum of AI capability.\n- **Real contrast:** \"ฟีเจอร์รองรับแบรนด์ใหญ่ ในราคา SME\" — \"expensive\" vs \"affordable\" is a real trade-off in the buyer's mind.\n\n**Test:** Ask \"does the reader ever have to choose between these two things?\" If yes, the contrast works. If no, the two sides aren't opposites — they're just unrelated concepts placed next to each other.\n\n**Name the Enemy.** Be the explicit alternative to the thing they already resent.\n> \"The CRM for people who hate Salesforce.\"\n\n**The \"Without\" Clause.** Promise the benefit, explicitly remove the associated cost.\n> \"Enterprise-grade security **without** the enterprise sales cycle.\"\n> \"Launch a rewards program **without** paying commissions on revenue.\"\n\n**Identity Callout.** Define who belongs. Define who doesn't.\n> \"Loyalty for **brands**, not dropshippers.\"\n> \"Built for **operators**, not executives who'll never log in.\"\n\n**Counter-Intuitive Truth.** Tell them to stop doing the thing they think they should be doing.\n> \"Stop optimizing for clicks. Start optimizing for retention.\"\n> \"Send fewer emails. Make more money.\"\n\n**Stakes / Cost of Inaction.** Show what the customer loses by doing nothing. Different from Objection Judo which removes fears — this *creates* urgency. Two angles:\n\n*Loss-based:* Show what slips away every day they don't act.\n> \"ทุกยอดซื้อที่ไม่ถูกบันทึก คือลูกค้าที่คุณไม่รู้จัก\"\n> \"ลูกค้าที่ไม่มีแต้มสะสม ไม่มีเหตุผลต้องกลับมา\"\n\n*FOMO-based:* Show that leading brands already use this — not acting means falling behind, not just standing still. The reader should feel that the brands they admire or compete with are already doing this, and not doing it makes their brand look behind the curve.\n> \"แบรนด์ชั้นนำใช้ Loyalty CRM ดูแลลูกค้าทุกราย — แบรนด์ที่ยังไม่มีระบบ ลูกค้ารู้สึกได้\"\n> \"ลูกค้ายุคนี้คาดหวังระบบสมาชิกที่ฉลาด แบรนด์ที่ยังใช้บัตรสะสมแต้มเริ่มดูตามไม่ทัน\"\n\nPeople are more motivated to avoid loss than to gain something. FOMO adds a social dimension — it's not just about losing customers, it's about looking outdated compared to peers.\n\n### 15. \"Why You\" Must Answer \"Why You\"\n\nIf a section asks \"ทำไมต้อง [Brand]?\" — every block under it must contain something that differentiates from competitors, not just describe standard features. Standard features belong in the features section. The \"why\" section must answer what you do that others don't, or what you do differently.\n\n- **Standard feature (not a \"why\"):** \"ให้คะแนนลูกค้าจากทุกพฤติกรรม\"\n- **Differentiator (actual \"why\"):** \"Loyalty Program ที่ไม่ได้แค่สะสมแต้ม — สร้างแคมเปญ วิเคราะห์ลูกค้า และดูแลลูกค้าแต่ละรายด้วย AI\"\n\nAsk: \"Could a competitor say the same thing?\" If yes, it's a feature, not a differentiator. Move it to the features section and find what's actually unique.\n\n### 16. Ads Headlines Must Drive Action\n\nSEO headlines can be informational — they answer a query. Ads headlines cannot afford to be informational alone. The reader already clicked an ad. They're considering you. The headline must create urgency, desire, or a direct challenge — not just describe a product category.\n\n- **Informational (fine for SEO):** \"ระบบ CRM สะสมแต้ม เพิ่มยอดซื้อซ้ำ ขับเคลื่อนด้วย AI\"\n- **Conversion-driven (ads):** Must make the reader feel something — cost of inaction, a possibility, or a direct challenge that pulls them in.\n\n_Source section truncated in seed; see `source_ref` for full text._", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#iii-persuasion-how-to-frame-the-message", "metadata": {"genre": "landing", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "iii-persuasion-how-to-frame-the-message", "part": 1, "feature_slug": "web-landing-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "79ecde415f1b8111a36e45b865dab608ce88cfd967a7189e865cf4f894aafea0", "truncated": true}, "is_active": true}, {"id": "920753ab-fd86-5897-933d-49ce94416d18", "feature_slug": "web-landing-copy", "title": "IV. Craft: Sentence-Level Discipline", "content": "---\n\n### 18. Punchy Specificity\n\nSpecific does not mean long. If it takes two lines to read, cut it. Every word must earn its place.\n\n**Kill filler.** Remove \"that helps you,\" \"enabling you to,\" \"in order to,\" \"designed for.\" These are verbal throat-clearing.\n\n**The One-Breath Test.** If you can't read the headline in a single short breath, rewrite.\n\n| Too Long | Punchy |\n|---|---|\n| \"We help you stop the manual process of pasting data from Stripe into Excel every single Monday morning.\" | \"Stop pasting Stripe data into Excel.\" |\n| \"A platform designed for high-growth brands that want to stand out from the competition.\" | \"Loyalty for category-leading brands.\" |\n| \"Our AI automatically segments your customers based on their purchase behavior and engagement history.\" | \"Auto-segments customers by what they buy and how they engage.\" |\n\nThe punchy version carries the same information with the scaffolding removed. Being descriptive and being concise are not opposites — they're the same discipline. Choose exact words, remove everything else.\n\n### 19. CTA: Shortest, Punchiest Line on the Page\n\nThe CTA headline is where hesitation lives. Long CTAs create friction. The reader is deciding whether to fill out a form — every extra word gives them time to reconsider.\n\nThe CTA does not need to re-explain the product. The reader has already scrolled the whole page. They know what it is. Just push them over the edge.\n\n- **Too padded:** \"พร้อมเพิ่มยอดซื้อซ้ำด้วยระบบ CRM หรือยัง?\"\n- **Punchy:** \"เพิ่มยอดซื้อซ้ำ เริ่มได้ใน 2 สัปดาห์\"\n\nPair the outcome with a speed/ease claim. That's it. No re-selling.\n\n### 20. Specificity Filter\n\nReference table. Every line you write, check it against this. Left column means rewrite.\n\n| Category | Generic (Delete) | Specific (Keep) |\n|---|---|---|\n| **Identity** | \"Next-gen loyalty platform.\" | \"The loyalty engine for category-leading brands.\" |\n| **Utility** | \"Flexible reward options.\" | \"Reward any action, not just purchases.\" |\n| **Value** | \"Affordable pricing.\" | \"Enterprise features, SME price tag.\" |\n| **Pain** | \"Stop manual work.\" | \"Stop pasting Stripe data into Excel.\" |\n| **Speed** | \"Fast integration.\" | \"Syncs orders in < 500ms.\" |\n| **Scope** | \"Comprehensive solution.\" | \"Points. Tiers. Referrals. Gift cards.\" |\n| **Tech** | \"AI-powered insights.\" | \"Predicts which customers will churn next month.\" |\n| **Customization** | \"Fully customizable.\" | \"ให้คะแนนได้มากกว่าแค่ยอดซื้อ — รีวิว ชวนเพื่อน Check-in ก็ให้ได้\" |\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#iv-craft-sentence-level-discipline", "metadata": {"genre": "landing", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "iv-craft-sentence-level-discipline", "part": 1, "feature_slug": "web-landing-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "e3fcba24f234fc55c11e3c000e09b40343ecd2fd8b0dcdddb07f1d6be8597eb9", "truncated": false}, "is_active": true}, {"id": "152ac3e8-d295-5a3a-b936-1c5d7fcad01d", "feature_slug": "web-landing-copy", "title": "Quick Decision Tree", "content": "For any line of copy:\n\n1. **Comprehension** — Does the reader know what it is and who it's for in 5 seconds?\n2. **Hero** — Is the sentence about the customer's situation, or about the brand?\n3. **Clarity** — Am I using a metaphor where a description should be? (Exception: punchy tagline that generates real emotion)\n4. **Precision** — Am I using a vague modifier where an example should be? Or a high-level word without a clear category container?\n5. **Balance** — Should I lead with outcome, mechanism, or identity for this audience? If using a heading + description pair, is the heading strategic and the description operational?\n6. **Category** — Would the reader know exactly which product type this is?\n7. **Validation** — Am I listing capabilities? Same abstraction level AND same grammatical form? Does each item convey the right meaning?\n8. **Visibility** — Is the feature abstract? Add narrative motion.\n9. **After-state** — Have I painted a concrete scene of the customer's life after using this?\n10. **Utility** — Am I describing features using the user's daily workflow verbs? Is AI the subject doing verbs, or a modifier bolted on?\n11. **Problem depth** — Am I addressing the external, internal, and philosophical layers? Is the pain real or manufactured?\n12. **Objections** — Am I handling fears inline? Is there a structured FAQ for bottom-of-page objections?\n13. **Trust** — Is social proof (numbers, logos) positioned early, before features?\n14. **Hooks** — Have I shown the cost of inaction AND the FOMO of falling behind peers? Do contrast structures set up real opposition?\n15. **Differentiation** — If this is a \"why us\" section, could a competitor say the same thing?\n16. **Intent** — Is the headline informational or conversion-driven? Does it match the page type?\n17. **Simplicity** — Is there a 3-step plan that makes the path feel easy?\n18. **Economy** — Can I read this in one breath? Is every word earning its place?\n19. **CTA** — Is the closing line the shortest, punchiest line on the page?\n20. **Specificity** — Would this pass the filter table?\n21. **Language** — Does the Thai read like Thai? English terms integrated naturally? Reader's vocabulary?\n22. **Keywords** — Is keyword usage calibrated to the page type (SEO vs. Ads)?\n\nIf it passes all twenty-two, ship it.\n\n---\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#quick-decision-tree", "metadata": {"genre": "landing", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "quick-decision-tree", "part": 1, "feature_slug": "web-landing-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "6d104a0e9d46f43bb83cb58da474f0305ff580a7ab9a762409d5525175fa34e6", "truncated": false}, "is_active": true}, {"id": "f67d3bcf-2fd6-5902-9f9b-0306bed0cadd", "feature_slug": "web-landing-copy", "title": "V. Language & Keywords", "content": "---\n\n### 21. Thai-English Language Rules\n\nContent will be written in Thai and English. Thai copy must read like it was written in Thai — not translated from English.\n\n**Core rule:** Write the thought in Thai first. If it sounds like something a Thai business owner would actually say, keep it. If it sounds like Google Translate output, rewrite from scratch.\n\n**English loanwords.** Terms that are universally used in English within the Thai business context stay in English. Do not force a Thai translation when none exists naturally.\n\n- **Keep in English:** AI, CRM, Dashboard, Loyalty Program, API, Shopify, LINE, Omnichannel, Marketplace, ROI, Churn\n- **Write in Thai:** everything else — especially verbs, benefits, and descriptions of what the product does\n\n**Examples:**\n\n- **Natural:** \"ใช้ AI วิเคราะห์พฤติกรรมลูกค้า\" — AI stays English, the rest is natural Thai.\n- **Forced:** \"ใช้ปัญญาประดิษฐ์ในการวิเคราะห์พฤติกรรมของลูกค้า\" — nobody says ปัญญาประดิษฐ์ in a business context.\n- **Natural:** \"เชื่อมต่อกับ Shopify ได้ทันที\" — Shopify stays English, verb is natural Thai.\n- **Forced:** \"สามารถทำการเชื่อมต่อระบบเข้ากับแพลตฟอร์ม Shopify ของคุณได้อย่างรวดเร็ว\" — over-formal, padded with unnecessary structure.\n\n**Watch for Thai filler patterns.** Thai copy tends to accumulate polite padding: สามารถ...ได้, ทำการ, เพื่อที่จะ, ช่วยให้คุณสามารถ. These are the Thai equivalent of \"enabling you to\" — cut them the same way.\n\n**English terms must integrate into Thai grammar.** Don't append English words to Thai sentences using แบบ, ในรูปแบบ, or ในลักษณะ as a bridge. If the term doesn't fit the sentence flow, restructure the sentence around it.\n\n- **Awkward graft:** \"สะสมแต้มได้ครบทุกช่องทาง แบบ Omnichannel\"\n- **Natural integration:** \"ระบบสะสมแต้ม Omnichannel — ขายที่ไหนก็ให้แต้มลูกค้าได้\"\n\nIn the first, \"แบบ Omnichannel\" is bolted on. In the second, \"Omnichannel\" sits as a modifier before the dash, and the Thai explanation follows naturally.\n\n**Use the reader's vocabulary, not the builder's.** If the audience is marketers, they \"ดึงรายงาน\" not \"เขียน Query.\" If the audience is business owners, they care about \"ยอดขาย\" not \"conversion rate.\" Always match the words the reader would use to describe their own daily work. If you wouldn't hear it in a meeting with that audience, don't put it on the page.\n\n### 22. Keyword Strategy\n\nEach prompt will specify two things: the **page type** (SEO or Ads) and the **primary keyword**. How you handle keywords differs between them.\n\n**SEO pages — optimize for ranking.** The primary objective is search visibility. Follow SEO best practices:\n\n- Place the keyword in the H1, at least one H2, the meta title, meta description, and the first 100 words.\n- Use it at a frequency that may feel slightly above natural — this is intentional. Search engines need repetition to understand page relevance.\n- Use semantic variations and related terms throughout the body to build topical authority.\n- The copy still needs to read well, but SEO density takes priority over conversational flow where the two conflict.\n\n**Ads pages — optimize for conversion.** The visitor already clicked an ad. They already searched the keyword. The primary objective is now conversion, not ranking.\n\n- Use the keyword enough that the reader feels they've landed on the right page — it should mirror their search intent and appear in the headline and early body copy.\n- Beyond that, let the keyword appear naturally. Do not repeat it artificially. Every additional instance should serve the reader, not a crawler.\n- The copy should feel like it's speaking to the reader, not performing for an algorithm.\n\n**The difference in practice:**\n\n| | SEO Page | Ads Page |\n|---|---|---|\n| **Goal** | Rank for the keyword | Convert the visitor |\n| **Keyword in H1** | Required | Required |\n| **Keyword density** | Higher than natural, per SEO best practice | Natural — enough to confirm relevance |\n| **Repetition logic** | Serve the algorithm | Serve the reader |\n| **Tone priority** | Informational, comprehensive | Direct, persuasive, concise |\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#v-language-keywords", "metadata": {"genre": "landing", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "v-language-keywords", "part": 1, "feature_slug": "web-landing-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "20aa125f3527da9314e2a214fbec4cba3e30f87612e7fd15b5f9188f68ae6b4e", "truncated": false}, "is_active": true}, {"id": "263c9a39-2e07-5e84-bc71-b4da9cf0df88", "feature_slug": "web-landing-copy", "title": "Web — Landing Page Copy — Overview", "content": "**When to use:** Product landing pages, homepage hero, feature LPs. 5-second clarity, customer-as-hero, CTAs, Thai/English voice.\n**Source:** `WEB_PAGE_COPY_PRINCIPLES.md` (Part 1)\n**Genre:** `landing`\n\nI. Foundation: What the Page Must Do in 5 Seconds", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md", "metadata": {"genre": "landing", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "overview", "part": 1, "feature_slug": "web-landing-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "722afacdb6ad9df20d454f89fef54ebbe5906b73bcdb2c968ef6c7b56d92bc3b", "truncated": false}, "is_active": true}, {"id": "aa593046-43b9-5eaa-9dae-724b45b904ca", "feature_slug": "web-page-copy", "title": "About this document", "content": "Single source of truth for **Rocket web content** — product landing pages, SEO blog/knowledge articles, on-page SEO signals, and internal link architecture.\n\n**Read first:** `CORE_WRITING_PRINCIPLES.md` for pyramid structure, MECE, same-level grouping, and specificity rules that apply across all formats.\n\n**Localization:** Non-Thai markets → `TRANSLATION_PHILOSOPHY.md` (separate doc).", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#about-this-document", "metadata": {"genre": "web", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "about-this-document", "feature_slug": "web-page-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "6b6776e070b4161c8df697c06096399fa961fecbb925e5fffeedc6ebc827d0dd", "truncated": false}, "is_active": true}]$seed_json$::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

